INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Steht hier die Hierarchie im Vordergrund?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Abläufe"}, {"text": "Ja", "correct": false, "because": "Prozesse zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dieser Struktur?', 3, '[{"text": "Effiziente Workflows", "correct": true, "because": "Optimierung der Abläufe"}, {"text": "Klare Befehle", "correct": false, "because": "Hierarchie sekundär"}, {"text": "Spezialisierung", "correct": false, "because": "Prozessübergreifend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt mir diese Organisation?', 5, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Optimierte Prozesse"}, {"text": "Kürzere Durchlaufzeiten", "correct": true, "because": "Flüssige Abläufe"}, {"text": "Starke Hierarchie", "correct": false, "because": "Prozessfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Prozesse werden optimiert. b) Abteilungen sind wichtiger.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abteilungen sekundär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei dieser Struktur?', 4, '[{"text": "Prozessfluss", "correct": false, "because": "Kern der Organisation"}, {"text": "Effizienz", "correct": false, "because": "Hauptziel"}, {"text": "Strikte Hierarchie", "correct": true, "because": "Prozesse im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob diese Struktur für kleine Teams geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Skalierbar für alle Größen"}, {"text": "Nein", "correct": false, "because": "Größe kein Hindernis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Ablaufoptimierung hier?', 3, '[{"text": "Zentrales Element", "correct": true, "because": "Effizienz steigern"}, {"text": "Nebensache", "correct": false, "because": "Kern der Struktur"}, {"text": "Zusatzaufgabe", "correct": false, "because": "Hauptfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente prägen diese Organisation?', 5, '[{"text": "Prozessorientierung", "correct": true, "because": "Abläufe im Mittelpunkt"}, {"text": "Workflow-Optimierung", "correct": true, "because": "Effizienz fördern"}, {"text": "Feste Abteilungen", "correct": false, "because": "Prozessübergreifend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Prozesse stehen im Fokus. b) Hierarchie ist entscheidend. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hierarchie zweitrangig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Prozessanalyse", "correct": false, "because": "Basis der Optimierung"}, {"text": "Workflow-Design", "correct": false, "because": "Kern der Struktur"}, {"text": "Zentrale Befehle", "correct": true, "because": "Prozesse im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Abteilungen hier wichtiger als Abläufe?', 2, '[{"text": "Nein", "correct": true, "because": "Prozesse dominieren"}, {"text": "Ja", "correct": false, "because": "Abläufe im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördern den Erfolg dieser Struktur?', 4, '[{"text": "Effiziente Abläufe", "correct": true, "because": "Zeit und Kosten sparen"}, {"text": "Klare Prozessdefinition", "correct": true, "because": "Verständnis schaffen"}, {"text": "Starke Führung", "correct": false, "because": "Prozessorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass hier alles chaotisch ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Prozesse sorgen für Ordnung"}, {"text": "Ja", "correct": false, "because": "Struktur durch Abläufe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in dieser Organisation?', 3, '[{"text": "Prozessoptimierung", "correct": true, "because": "Effizienz steigern"}, {"text": "Abteilungsgrenzen", "correct": false, "because": "Sekundär"}, {"text": "Zentrale Steuerung", "correct": false, "because": "Prozessfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Workflows werden analysiert. b) Hierarchie steht über allem.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hierarchie zweitrangig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile könnten auftreten?', 5, '[{"text": "Komplexe Koordination", "correct": true, "because": "Prozesse überschneiden sich"}, {"text": "Verlust von Flexibilität", "correct": true, "because": "Feste Abläufe"}, {"text": "Zu viel Hierarchie", "correct": false, "because": "Prozessorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Prozessdesign", "correct": false, "because": "Kern der Struktur"}, {"text": "Effizienz", "correct": false, "because": "Hauptziel"}, {"text": "Abteilungsautonomie", "correct": true, "because": "Prozesse übergreifend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördert diese Struktur Abteilungsdenken?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Abläufe"}, {"text": "Ja", "correct": false, "because": "Prozesse im Vordergrund"}]'),
